package com.example.rokidkeyboardbridge;
import java.util.*;
public final class RestNaturalIdleTest {
 static int n;static void ok(boolean v,String m){n++;if(!v)throw new AssertionError(m);}
 public static void main(String[] args){NaturalPosePolicy p=new NaturalPosePolicy();p.user("ねそべって",10000);ok(p.select(0,21999,1,false,false,true,false)==0,"first change holds for twelve seconds");ok(p.select(0,22000,1,false,false,true,false)==10,"generic lying is not permanently fixed");ok(p.select(0,23000,1,false,false,true,false)==10,"listening standby keeps variation");p.mode(1,23000,false);ok(p.active(),"repeated listening mode does not cancel pose");p.mode(1,23100,true);ok(!p.active(),"actual AI work retains priority");
 p=new NaturalPosePolicy();p.user("寝そべって",10000);p.user("合成の普通の質問です",18000);p.mode(1,18000,true);p.select(0,21000,1,false,false,true,true);p.mode(2,21000,false);p.select(0,23000,2,false,false,true,false);p.mode(1,24000,false);ok(p.select(0,26000,1,false,false,true,false)==10,"ordinary dialogue does not restart twenty-two-second deadline");
 p=new NaturalPosePolicy();p.user("寝そべって",10000);Set<Integer> clips=new HashSet<>();int starts=0;boolean previous=false;for(long at=10000;at<190000;at+=250){int motion=p.select(0,at,1,false,false,true,false);if(p.active()&&!previous){clips.add(motion);starts++;}previous=p.active();}ok(clips.containsAll(Arrays.asList(10,1,2)),"side rest roll and stretch all occur while listening");ok(starts>=3&&starts<=5,"bounded automatic cadence");
 for(int variant=0;variant<9;variant++)ok(NaturalPosePolicy.alternative(0,variant)==new int[]{10,1,2,12,13,14}[variant%6],"deterministic non-repeating lying variety");
 for(int protectedMode=0;protectedMode<5;protectedMode++){p=new NaturalPosePolicy();p.user("寝そべって",10000);int selected=p.select(0,30000,protectedMode==0?2:1,protectedMode==1,protectedMode==2,protectedMode!=3,protectedMode==4);ok(selected==0&&!p.active(),"speech navigation manual-face off and request priority");}
 p=new NaturalPosePolicy();p.user("寝そべって",10000);p.user("ポーズを固定して",11000);ok(p.select(0,100000,1,false,false,true,false)==0&&!p.active(),"explicit fixed mode stays fixed");p=new NaturalPosePolicy();p.user("寝そべって",10000);p.user("寝たまま立膝にして",11000);ok(p.select(5,100000,1,false,false,true,false)==5&&!p.active(),"specific knee instruction is never undone");System.out.println("PASS "+n+" lying standby/deadline/variety regression checks");}
}
